// === Tab: Sketch ===
// By Roni Kaufman
// Inspired by the work of Hiroshi Kawano

var colors; // colors[0] is always black
var size;
var probChangeColor;
var currentColor;

function setup() {
  createCanvas(400, 400);
  // noLoop() removed for animation

  size = width/40;
  probChangeColor = 0.25;

  noStroke();
}

function draw() {
  var black = color(10, 10, 10);
  var white = color(247, 243, 242);
  var color1 = color(0, 119, 225); // blue
  var color2 = color(245, 210, 22); // yellow
  var color3 = color(252, 53, 3); // red

  colors = [black, white, white, color1, color2, color3];
  currentColor = randomColor();

  createComposition();
  addBorder();
}

function createComposition() {
  for (var y = 0; y < height; y += (Math.max(0.001, Math.abs(size)) || 1)) {
    for (var x = 0; x < width; x += (Math.max(0.001, Math.abs(size)) || 1)) {
      if (random(1) < probChangeColor) {
        currentColor = randomColor();
      }
      fill(currentColor);
      square(x, y, size);
    }
  }
}

function addBorder() {
  strokeWeight(2);
  stroke(colors[0]);
  line(0, 0, 0, height);
  line(0, height, width, height);
  line(width, height, width, 0);
  line(width, 0, 0, 0);
  noStroke();
}

function randomColor() {
  return colors[floor(random(colors.length))];
}

function keyPressed() {
  if (key === " ") {
    draw();
  }
}
